RULES = 'Defaults:tak !requiretty\ntak ALL=(root) NOPASSWD: /usr/local/libexec/taks-state-backup inventory\ntak ALL=(root) NOPASSWD: /usr/local/libexec/taks-state-backup users\ntak ALL=(root) NOPASSWD: /usr/local/libexec/taks-state-backup certs\ntak ALL=(root) NOPASSWD: /usr/local/libexec/taks-state-backup cot_state\ntak ALL=(root) NOPASSWD: /usr/local/libexec/taks-state-backup config\ntak ALL=(root) NOPASSWD: /usr/local/libexec/taks-state-backup takctl_state\ntak ALL=(root) NOPASSWD: /usr/local/libexec/taks-state-backup martine_state\ntak ALL=(root) NOPASSWD: /usr/local/libexec/taks-state-backup documents\ntak ALL=(root) NOPASSWD: /usr/local/libexec/taks-state-backup replay_state\n'

def main():
    if os.geteuid() != 0:
        raise SystemExit('Run as root on the existing TAK node')
    if not Path('/opt/tak/tools/takctl/conf.d/node.conf').is_file():
        raise SystemExit('This is not a provisioned TAK node; no changes made')
    with tempfile.TemporaryDirectory(prefix='taks-backup-bridge-') as tmp:
        rules = Path(tmp) / 'sudoers'
        rules.write_text(RULES)
        subprocess.run(['visudo', '-cf', str(rules)], check=True)
        for name, (content, mode) in PAYLOADS.items():
            path = Path(name)
            path.parent.mkdir(parents=True, exist_ok=True)
            if path.is_file():
                shutil.copy2(path, Path(tmp) / (path.name + '.previous'))
            staged = Path(tmp) / path.name
            staged.write_text(content)
            subprocess.run(['install', '-o', 'root', '-g', 'tak' if str(path).startswith('/opt/tak/') else 'root', '-m', oct(mode)[2:], str(staged), str(path)], check=True)
        subprocess.run(['install', '-o', 'root', '-g', 'root', '-m', '0440', str(rules), '/etc/sudoers.d/taks-state-backup'], check=True)
        subprocess.run(['sudo', '-n', '-u', 'tak', 'sudo', '-n', '/usr/local/libexec/taks-state-backup', 'inventory'], check=True, stdout=subprocess.DEVNULL)
        subprocess.run(['systemctl', 'restart', 'takctl-web.service'], check=True)
    print('State backup bridge installed and checked; current node data is unchanged.')

if __name__ == '__main__':
    main()
